const EDGE_XREF_0_PROJECT_SQL = `SELECT ?1 AS "from_span_id", ?2 AS "to_repo_id", ?3 AS "to_rev_id", ?4 AS "to_path", (SELECT s."__id" FROM "__str" s WHERE s."content" = 'none') AS "col5", ?5 AS "kind"`;
